const bytes = Array.from(msg.payload.serviceDataList[0].legacyDataList || []);

if (bytes.length === 0) {
    return;
}

const deviceInfo = bytes[0];
const version = deviceInfo >> 5;

const encrypted = (deviceInfo & 0x01) !== 0;

if (version !== 2) {
    return;
}

if (encrypted) {
    return;
}

const result = {};

let i = 1;

while (i < bytes.length) {
    const objectId = bytes[i++];

    switch (objectId) {
        case 0x00:
            result.packetId = bytes[i++];
            break;

        case 0x01:
            result.battery = bytes[i++];
            break;

        case 0x02: {
            if (i + 1 >= bytes.length) {
                continue;
            }

            let value = bytes[i] | (bytes[i + 1] << 8);
            if (value & 0x8000) {
                value -= 0x10000;
            }

            result.temperature = value * 0.01;

            i += 2;
            break;
        }

        case 0x03: {
            if (i + 1 >= bytes.length) {
                continue;
            }

            const value = bytes[i] | (bytes[i + 1] << 8);

            result.humidity = value * 0.01;

            i += 2;
            break;
        }

        case 0x0c: {
            if (i + 1 >= bytes.length) {
                continue;
            }

            const value = bytes[i] | (bytes[i + 1] << 8);

            result.voltage = value * 0.001;

            i += 2;
            break;
        }

        case 0x10:
            result.power = bytes[i++] !== 0;
            break;

        case 0x11:
            result.opening = bytes[i++] !== 0;
            break;

        default:
            continue;
    }
}

if (Object.keys(result).length === 0) {
    return;
}
msg.payload = {
    address: msg.payload.address,
    rssi: msg.payload.rssi,
    ...result,
};
return msg;
